<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
// Included only by setup-wizard.php; all controls describe organization configuration.
$prefix = 'setup_field[' . $setup_field_index . ']';
$field = $setup_field_row['definition'];
$policy = ( new \Certloom\Application\Fields\FieldCollectionForm() )->normalize( $setup_field_row['collection'], $field );
if ( ! is_wp_error( $policy ) && null !== $policy ) { $field['collection_policy'] = $policy; }
elseif ( null === $policy ) { unset( $field['collection_policy'] ); }
$custom = ! empty( $setup_field_row['custom'] );
?>
<article class="certloom-setup-field" data-certloom-setup-field <?php echo ! empty( $setup_field_row['enabled'] ) ? 'data-enabled' : ''; ?>>
	<label class="certloom-setup-field__choice"><input type="checkbox" name="<?php echo esc_attr( $prefix ); ?>[enabled]" value="1" <?php checked( ! empty( $setup_field_row['enabled'] ) ); ?> data-certloom-setup-field-enabled><span data-certloom-setup-field-title><?php echo esc_html( '' === trim( $setup_field_row['label'] ) ? __( 'New custom field', 'certloom' ) : $setup_field_row['label'] ); ?></span><?php if ( ! empty( $setup_field_row['new'] ) ) : ?><small><?php esc_html_e( 'New field', 'certloom' ); ?></small><?php endif; ?></label>
	<fieldset class="certloom-setup-field__settings" data-certloom-setup-field-settings <?php disabled( empty( $setup_field_row['enabled'] ) ); ?>>
		<legend class="screen-reader-text"><?php echo esc_html( $setup_field_row['label'] ?: __( 'Custom field settings', 'certloom' ) ); ?></legend>
		<?php if ( $custom ) : ?>
		<div class="certloom-setup-v2-data-grid"><label class="certloom-setup-v2-field"><span><?php esc_html_e( 'Field name', 'certloom' ); ?></span><input type="text" name="<?php echo esc_attr( $prefix ); ?>[label]" maxlength="100" value="<?php echo esc_attr( $setup_field_row['label'] ); ?>" data-certloom-setup-field-label></label><label class="certloom-setup-v2-field"><span><?php esc_html_e( 'Field key', 'certloom' ); ?></span><input type="text" name="<?php echo esc_attr( $prefix ); ?>[key]" maxlength="64" value="<?php echo esc_attr( $setup_field_row['key'] ); ?>" pattern="[a-z][a-z0-9_\-]{0,63}" data-certloom-setup-field-key><small><?php esc_html_e( 'A stable name for designs and integrations, for example father_name.', 'certloom' ); ?></small></label><label class="certloom-setup-v2-field"><span><?php esc_html_e( 'Answer format', 'certloom' ); ?></span><select name="<?php echo esc_attr( $prefix ); ?>[type]"><?php foreach ( array( 'text' => __( 'Text (use for ID numbers)', 'certloom' ), 'textarea' => __( 'Long text', 'certloom' ), 'number' => __( 'Number', 'certloom' ), 'date' => __( 'Date', 'certloom' ) ) as $type => $label ) : ?><option value="<?php echo esc_attr( $type ); ?>" <?php selected( $type, $setup_field_row['type'] ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></label></div>
		<?php else : foreach ( array( 'key', 'label', 'type' ) as $key ) : ?><input type="hidden" name="<?php echo esc_attr( $prefix ); ?>[<?php echo esc_attr( $key ); ?>]" value="<?php echo esc_attr( $setup_field_row[ $key ] ); ?>"><?php endforeach; endif; ?>
		<label class="certloom-setup-v2-field"><span><?php esc_html_e( 'Does this Program need it?', 'certloom' ); ?></span><select name="<?php echo esc_attr( $prefix ); ?>[requirement]"><?php foreach ( array( 'optional' => __( 'Optional', 'certloom' ), 'required' => __( 'Required before issuing', 'certloom' ), 'inherit' => __( 'Use organization / site rule', 'certloom' ), 'exclude' => __( 'Do not use in this Program', 'certloom' ) ) as $value => $label ) : ?><option value="<?php echo esc_attr( $value ); ?>" <?php selected( $value, $setup_field_row['requirement'] ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></label>
		<?php if ( ( new \Certloom\Application\Fields\FieldCollectionPolicy() )->supports_policy( $field ) ) : ( new \Certloom\Infrastructure\Admin\FieldCollectionControls() )->render( $field, 0, $prefix . '[collection]' ); else : foreach ( ( new \Certloom\Application\Setup\WizardFieldSetup() )->form_collection( $field ) as $key => $value ) : ?><input type="hidden" name="<?php echo esc_attr( $prefix ); ?>[collection][<?php echo esc_attr( $key ); ?>]" value="<?php echo esc_attr( $value ); ?>"><?php endforeach; ?><p class="description"><?php esc_html_e( 'This identity field keeps its existing account source.', 'certloom' ); ?></p><?php endif; ?>
		<label class="certloom-setup-v2-field" data-certloom-setup-default><span><?php esc_html_e( 'Shared value for this Program', 'certloom' ); ?></span><textarea name="<?php echo esc_attr( $prefix ); ?>[default_value]" maxlength="8192" rows="2"><?php echo esc_textarea( $setup_field_row['default_value'] ); ?></textarea><small><?php esc_html_e( 'Used for everyone in this Program. Choose Organization staff and Program above. Leave blank to set it later.', 'certloom' ); ?></small></label>
		<?php if ( $custom ) : ?><button type="button" class="button-link" data-certloom-setup-field-remove><?php esc_html_e( 'Remove field', 'certloom' ); ?></button><?php endif; ?>
	</fieldset>
</article>
